diff --git a/src/cache.ts b/src/cache.ts
index 9fa8c53..e6edc5c 100644
--- a/src/cache.ts
+++ b/src/cache.ts
@@ -1,19 +1,68 @@
+import { readFileSync, writeFileSync, existsSync } from "fs";
+import { join } from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const STORE_PATH = join(process.cwd(), ".cache", "sessions.json");
+const inMemory = new Map<string, Entry>();
+let isDirty = false;
+
+const ensureStoreExists = (): void => {
+  if (!existsSync(STORE_PATH)) {
+    const dir = join(process.cwd(), ".cache");
+    if (!existsSync(dir)) {
+      require("fs").mkdirSync(dir, { recursive: true });
+    }
+    writeFileSync(STORE_PATH, "{}");
+  }
+};
+
+const loadFromDisk = (): void => {
+  try {
+    ensureStoreExists();
+    const data = readFileSync(STORE_PATH, "utf-8");
+    const parsed = JSON.parse(data);
+    inMemory.clear();
+    Object.entries(parsed).forEach(([key, entry]) => {
+      inMemory.set(key, entry as Entry);
+    });
+  } catch {
+    inMemory.clear();
+  }
+};
+
+const saveToDisk = (): void => {
+  try {
+    const obj: Record<string, Entry> = {};
+    inMemory.forEach((entry, key) => {
+      obj[key] = entry;
+    });
+    writeFileSync(STORE_PATH, JSON.stringify(obj));
+    isDirty = false;
+  } catch {
+    // Silently fail if we can't write to disk
+  }
+};
+
+// Load persisted sessions on startup
+loadFromDisk();

 export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  inMemory.set(key, { value, expiresAt: Date.now() + ttlMs });
+  isDirty = true;
+  saveToDisk();
 };

 export const get = (key: string): string | null => {
-  const entry = store.get(key);
+  const entry = inMemory.get(key);
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
-    store.delete(key);
+    inMemory.delete(key);
+    isDirty = true;
+    saveToDisk();
     return null;
   }
   return entry.value;
